import { desc, eq, or, sql, type SQL } from 'drizzle-orm';
import type {
  VariantHistoryStatus,
  VariantIndexEntryInput,
} from '@rivet/core/types/variant-history';
import { closeDatabase, transaction } from '../library/database';
import { openProjectMetadataDatabase } from './database';
import type { ProjectMetadataMigration } from './migrations';
import { metadataState, variants } from './schema';

type Database = Awaited<ReturnType<typeof openProjectMetadataDatabase>>['db'];

export class ProjectMetadataRecords {
  private constructor(
    private readonly db: Database,
    readonly wasUpgraded: boolean,
  ) {}

  static async open(
    databasePath: string,
    migrations: readonly ProjectMetadataMigration[],
  ): Promise<ProjectMetadataRecords> {
    const { db, wasUpgraded } = await openProjectMetadataDatabase({
      databasePath,
      migrations,
    });
    return new ProjectMetadataRecords(db, wasUpgraded);
  }

  transaction<T>(operation: () => T): T {
    return transaction(this.db, operation);
  }

  clearVariants(): void {
    this.db.delete(variants).run();
  }

  upsert({
    manifest,
    manifestMtimeMs,
    hasStaticPreview,
  }: VariantIndexEntryInput): void {
    const values = {
      sessionId: manifest.sessionId,
      variantId: manifest.variantId,
      label: manifest.label,
      brief: manifest.brief,
      sessionPrompt: manifest.sessionPrompt,
      runLabel: manifest.runLabel ?? null,
      status: manifest.status,
      createdAt: manifest.createdAt,
      statusChangedAt: manifest.statusChangedAt,
      hasTree: Boolean(manifest.tree),
      serveKind: manifest.serve?.kind ?? null,
      hasStaticPreview,
      manifestMtimeMs: Math.round(manifestMtimeMs),
      manifest,
    };
    this.db
      .insert(variants)
      .values(values)
      .onConflictDoUpdate({
        target: [variants.sessionId, variants.variantId],
        set: values,
      })
      .run();
  }

  list({ status, limit }: { status?: VariantHistoryStatus; limit?: number }) {
    return this.selectEntries({
      condition: status ? eq(variants.status, status) : undefined,
      limit,
    });
  }

  search({ query, limit }: { query: string; limit?: number }) {
    const escaped = query.replace(/[\\%_]/g, (match) => `\\${match}`);
    const pattern = `%${escaped}%`;
    const condition = or(
      ...[
        variants.label,
        variants.brief,
        variants.sessionPrompt,
        variants.runLabel,
      ].map((column) => sql`${column} LIKE ${pattern} ESCAPE '\\'`),
    );
    return this.selectEntries({ condition, limit });
  }

  readState(key: string): string | null {
    return (
      this.db
        .select({ value: metadataState.value })
        .from(metadataState)
        .where(eq(metadataState.key, key))
        .get()?.value ?? null
    );
  }

  writeState(key: string, value: string): void {
    const updatedAt = new Date().toISOString();
    this.db
      .insert(metadataState)
      .values({ key, value, updatedAt })
      .onConflictDoUpdate({
        target: metadataState.key,
        set: { value, updatedAt },
      })
      .run();
  }

  close(): void {
    closeDatabase(this.db);
  }

  private selectEntries({
    condition,
    limit,
  }: {
    condition?: SQL;
    limit?: number;
  }) {
    const query = this.db
      .select({
        manifest: variants.manifest,
        hasStaticPreview: variants.hasStaticPreview,
      })
      .from(variants)
      .where(condition)
      .orderBy(
        desc(variants.createdAt),
        variants.sessionId,
        variants.variantId,
      );
    return limit !== undefined && limit > 0
      ? query.limit(limit).all()
      : query.all();
  }
}
